import { motion } from "motion/react";

function PerceptualDuration() {
  return (
    <motion.div
      animate={{ scale: 1 }}
      transition={{
        type: "spring",
        duration: 0.5,
        bounce: 0.2,
      }}
    />
  );
}

// duration: perceptual duration in seconds
// bounce: 0 = no bounce, 1 = maximum bounce
